-- Northern Gun Two's adventuring gear, Bio-Brace, robot and vehicle upgrades and two bionic systems.
-- 28 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~334-northern-gun-2-adventuring-gear.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
--
-- Northern Gun Two's Adventuring Gear (printed p.251-254), the Medical
-- Bio-Brace (p.254-255), the Robot and Vehicle Upgrades (p.255-256) and the
-- two NG bionic systems on p.256. 28 rows, every one queried by slug and name
-- against production --remote on 2026-11-17 and absent there. Every figure was
-- read off the page; the Habitation Module's M.D.C. by Type block and the
-- Crate's M.D.C. line were read off renders.
--
-- Variants. A variant with its own price AND its own protection or weight is a
-- row of its own (the three Habitation Module models, the M.D.C. versions of
-- the Overland pack, the Combat & Survival Shelter and the NG-CCS). A variant
-- that differs only in price (plug-in or fixed appliances, the SleepSafe tent
-- sizes, the Winterization Kit by vehicle type, the exterior or concealed thigh
-- holster) is one row, its low price in cost and the rest in cost_note.
--
-- The NG-S2 Basic Survival Pack's contents carry no price of their own and are
-- described in the pack's row, not given rows; the catalog already holds
-- generic canteens, climbing and survival kits from other books.
--
-- HELD AND LEFT AS THEY ARE, not updated or re-cited here:
--   rocket-boots (Juicer Uprising p.67-68) is the NG-RB-5 Rocket Boots of p.252:
--     same 60 ft jump, 20 jumps per E-Clip, 30,000 credits. This book adds
--     M.D.C. 12 per boot and a 2,000-4,000 build-in cost against the held 2,000.
--   ng-all-in-one-utility-belt (Adventures in Dinosaur Swamp p.158), p.251:
--     same item, same 400/350 credits.
--   ng-overland-harness-and-frame-pack (Dinosaur Swamp p.158), p.252-253: same
--     700 credits; this book adds 50 S.D.C. for the standard pack.
--   ng-icss-combat-and-survival-shelter (Dinosaur Swamp p.158), p.254: the same
--     three-person tent; held at 800-1000 credits, this book prints 1,000.
--   ng-ccs-command-and-control-shelter (Dinosaur Swamp p.158), p.254: held at
--     3,000 credits; this book prints 3,600 for the S.D.C. fabric.
--   ng-drone-control-command-gauntlet (this book p.244-245), named again on
--     p.251 inside the Robosistant's entry at the same 5,200 credits.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ng-all-surface-climbing-gear', 'All-Surface Climbing Gear', 'rifts', 'gear', NULL, 18000, '18,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A set of climbing gloves and boots whose grip mixes gecko-hair fibres, electromagnets, suction cups and claws; a microchip picks whichever suits the surface being scaled. Gives +10% to the Climbing skill.', 'Rifts World Book 34: Northern Gun Two p.251', NULL),
  ('ng-s2-basic-survival-pack', 'NG-S2 Basic Survival Pack', 'rifts', 'gear', NULL, 2400, '2,400 credits for the whole pack; the contents are not priced separately.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s wilderness starter kit, popular with adventurers and travelers. Contents: two 32 oz (0.95 l) canteens, each with a filter, six purification pellets and a belt pouch; a climbing kit (50 ft/15.2 m of cord rated to 500 lbs/225 kg, climbing gloves, four ceramic spikes, a small mallet); a compass/inertial mapper that tracks distance and heading (+5% Land Navigation) with a mirrored face for sun signals or Morse; a fire starter kit (flint or magnesium sparker, 24 wooden matches, a refillable lighter, cotton tinder); a first aid kit (gauze, 48 adhesive bandages, tape, scissors, pocket knife, protein healing salve); a flashlight with four 48-hour batteries; 10 MRE rations; a hunting and fishing kit of wire, line, hooks and pulleys for fishing or snares; three saw-wires, hard serrated wires with ring handles that cut wood, stone and S.D.C. metal; a 5 mile (8 km) short-range radio; a one-person sleeping bag; four hand flares that rise 400 ft (122 m) and burn 7 seconds; soap and a washcloth; and a survival knife, hatchet and wooden cross.', 'Rifts World Book 34: Northern Gun Two p.251-252', NULL),
  ('ng-electronic-auto-lock-pick', 'Electronic Auto-Lock Pick', 'rifts', 'gear', NULL, 8000, '8,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A computerised pick made for high-tech locks. Gives +10% to the Lock Picking and Locksmith skills.', 'Rifts World Book 34: Northern Gun Two p.252', NULL),
  ('ng-heads-up-display-glasses', 'Heads-Up Display Glasses', 'rifts', 'gear', NULL, 1000, '1,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Ordinary-looking sunglasses or goggles with a small computer and a wireless receiver, so the lenses show data the way a helmet HUD does. The feed can come from sensors the wearer carries, or be sent from a sensor array, a camera, or an ally in a vehicle, robot, power armor or command post.', 'Rifts World Book 34: Northern Gun Two p.252', NULL),
  ('ng-ipb-10-infrared-photo-binoculars', 'NG-IPB-10 Infrared Photo Binoculars', 'rifts', 'gear', NULL, 50000, '50,000 credits.', NULL, 0, '2.5 miles (4 km) viewing; transmits up to 1 mile (1.6 km)', NULL, NULL, NULL, NULL, NULL, 'Digitally enhanced infrared binoculars with one-button auto-focus and zoom. They store 10,000 high-quality stills (twice that at low resolution) or six hours of video, and can send what they record up to a mile or feed it into a communications system, command center or a pilot''s display for longer reach. Forward observers prize them for relaying a view in real time.', 'Rifts World Book 34: Northern Gun Two p.252', NULL),
  ('ng-overland-harness-and-frame-pack-mdc', 'NG "Overland" Harness and Frame Pack, M.D.C. Version', 'rifts', 'gear', NULL, 2700, '2,700 credits, against 700 for the standard pack.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 3, 'The Overland external-frame pack made from mega-damage fabric instead of the standard pack''s heavy-duty 50 S.D.C. material, for 3 M.D.C. in all. Otherwise the same harness: chest pouches, compass pouch, quick-release main compartment of 3,000 cubic inches (49,000 cc) and a 500 cubic inch (8,200 cc) detachable daypack. The standard pack is held as ng-overland-harness-and-frame-pack.', 'Rifts World Book 34: Northern Gun Two p.252-253', NULL),
  ('ng-sleepsafe-personal-field-shelter', 'SleepSafe Personal Field Shelter ("The Crate")', 'rifts', 'gear', 6, 11500, '11,500 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 25, 'A folding, man-sized box, long and narrow like a coffin, that locks from inside and has a battery nightlight; bedding is laid inside it. It comes with a Sensor Sentry whose alarm wakes the occupant by light, sound or vibration, and the Sentry can be set apart, say up a tree, and signal the box remotely. Not air or water tight: it sinks in water and lets gas and smoke in. No use to anyone claustrophobic, and popular with vampires, to Northern Gun''s dismay.', 'Rifts World Book 34: Northern Gun Two p.253', NULL),
  ('ng-sleepsafe-sensor-sentry', 'SleepSafe "Sensor Sentry" Warning System', 'rifts', 'gear', 2, 4500, '4,500 credits each.', NULL, 0, 'Cameras and laser-motion sensor 100 ft (30.5 m) in a 90 degree cone; audio up to 2 miles (3.2 km) in the wild; transmits 1.6 miles (2.6 km)', '192 hours of use per standard E-Clip, and records all 192', NULL, NULL, NULL, NULL, 'A palm-sized (1x3x5 inch) watch unit with a visual camera, an infrared camera, a laser-motion sensor and a listening system that recognises gunfire, explosions, engines and voices. It ships with an E-Clip-powered receiver that alerts by buzz, vibration, ringing, a spoken warning or flashing lights, silently if wished, and shows a live feed or replays whatever tripped it; the feed can go on to a helmet HUD or vehicle screen. Its simple program flags humanoids and dangerous animals. Hearing in the wild reaches 2 miles for gunfire or a monster''s roar and 2,500 ft (762 m) for footsteps of giant robots or vehicles crashing through brush; city noise cuts it to about 100 ft, and a quiet building to about 500 ft (152 m). Used by NG police and Monster Responders, adventurers, spies and thieves; easy to spot, and to steal, unless hidden.', 'Rifts World Book 34: Northern Gun Two p.253-254', NULL),
  ('ng-sleepsafe-sentry-tent', '"SleepSafe Sentry" Tent', 'rifts', 'gear', 5, 200, 'By size: 1 person 200, 2 person 400, 3 person 700, 4 person 1,000, 6 person 1,500, 8 person 2,000, 12 person 2,800, 20 person 3,500 credits. Weight by size: 5, 7, 10, 14, 18, 21, 26 and 48 lbs.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A line of tents built around the Sensor Sentry, each with a prominent mount for the unit; when it detects a threat it signals the receiver inside, as an audible or a silent alert. Sizes run from a one-person pup tent to a 20-person fabric building, and every one collects rainwater. The Sensor Sentry is bought separately (ng-sleepsafe-sensor-sentry).', 'Rifts World Book 34: Northern Gun Two p.254', NULL),
  ('ng-standard-tent-two-person', 'NG Standard Tent: Two-Person', 'rifts', 'gear', NULL, 300, '300 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Folds to the size of a paperback and sleeps two in comfort. Insulated against rain and cold down to -20 F (-29 C). It gathers the moisture its occupants give off, stretching carried water by 20%, so eight days'' supply lasts ten.', 'Rifts World Book 34: Northern Gun Two p.254', NULL),
  ('ng-icss-combat-and-survival-shelter-mdc', 'NG Combat & Survival Shelter, M.D.C. Version', 'rifts', 'gear', 5, 6000, '6,000 credits, against 1,000 for the S.D.C. tent.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 8, 'The three-person Combat & Survival Shelter woven from mega-damage micro-fibres, 8 M.D.C. in all. Same tent otherwise: flame resistant, waterproof, insulated to -60 F (-51 C), rainwater collection, 3 ft tall, 5 ft wide and 6 ft long, a 72-hour battery light, and two people pitch it in 5 minutes. The S.D.C. tent is held as ng-icss-combat-and-survival-shelter.', 'Rifts World Book 34: Northern Gun Two p.254', NULL),
  ('ng-ccs-command-and-control-shelter-mdc', 'NG Command and Control Shelter (NG-CCS), M.D.C. Version', 'rifts', 'gear', 18, 36000, '36,000 credits, against 3,600 for the S.D.C. fabric in this book. M.D.C. is 8 for every 7 ft (2.1 m) wide section of material.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 8, 'The modular NG-CCS hut tent (8 ft tall, 9 ft wide, 22 ft long) in mega-damage micro-fibre, 8 M.D.C. per seven-foot section. Four people raise it in under 20 minutes; shelters link into sealable rooms and take HVAC, N.B.C. and surgical add-ons; the lights run 144 hours on battery or off a generator, E-Clips or a Techno-Wizard supply. The S.D.C. shelter is held as ng-ccs-command-and-control-shelter.', 'Rifts World Book 34: Northern Gun Two p.254', NULL),
  ('ng-medical-bio-brace', 'Medical: Bio-Brace', 'rifts', 'gear', NULL, 11500, '11,500 credits per brace; braces are made for arms, legs, neck and torso.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 6, 'A cybernetic splint whose sensors scan a broken limb, push the bone back into place and hold it as a light cast would, so no medical skill is needed; it buys hours or days until a Body Fixer or Healer can see to it, but a severe break (six or more fractures, or bone through the skin) should get real care within 12 hours. Braced leg: speed -20%, -1 initiative, -2 dodge, no kicks or jumps, -30% to leg skills such as Acrobatics, Climbing, Prowl and Swim. Braced arm: melee damage halved, P.S. -20% for that limb, -10% to dexterity skills and -40% to strength skills, lifts a third as much, -1 to strike, parry, pin, disarm and entangle, no power punch, and each punch costs two melee attacks. Double these for a severe break. Torso or neck (ribs, or a spine without nerve damage): P.S. and Spd -60%, -30% to all skills, combat bonuses to zero, lifting over 10 lbs (4.5 kg) risks paralysis, no kicks or jumps, and each punch costs two attacks, does half damage and deals 1D6 Hit Points/S.D.C. to the wearer. The brace has 6 M.D.C.; at zero it is destroyed and the limb is useless.', 'Rifts World Book 34: Northern Gun Two p.254-255', NULL),
  ('ng-robot-habitation-module-fabric-carrier', 'Combat Robot Habitation Module: Fabric Carrier Model', 'rifts', 'gear', 110, 10500, '10,500 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 25, 'A lightly armoured sling-tent of M.D.C. fabric and polymer plating, hung from a giant humanoid robot''s neck and carried on its back or front like a baby carrier, so the pilot can sleep stretched out a few yards from the controls. Inside are two fold-out cots and two hammock sleepers; it packs into a large bag that hooks on the robot''s back, hip or shoulder. 25 M.D.C. in total.', 'Rifts World Book 34: Northern Gun Two p.255', NULL),
  ('ng-robot-habitation-module-fabric-patio', 'Combat Robot Habitation Module: Fabric and Polymer Patio Model', 'rifts', 'gear', 320, 56000, '56,000 credits; a second rain reservoir is 500 more.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 20, 'A larger hard-floored fabric habitat slung from a robot''s neck, shoulder, chest or back, 10 ft wide, 7 ft deep and 5 ft tall, with a 4 ft patio past its zippered door. It holds a chemical-toilet bathroom with sink and shower, two bunk cots, four folding chairs, a fold-down table and coverable viewing slits; a 40 gallon (151 l) roof reservoir collects rain, and with the top off the whole module holds 1,300 gallons or serves as a crow''s nest. Two people build it in 30 minutes. 20 M.D.C. per side, roof and floor included, on a plastic frame. Also usable on large vehicles or the ground.', 'Rifts World Book 34: Northern Gun Two p.255', NULL),
  ('ng-robot-habitation-module-deluxe-armored', 'Combat Robot Habitation Module: Deluxe Armored Patio Model', 'rifts', 'gear', 540, 100000, '100,000 credits; a second rain reservoir is 500 more.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 40, 'The fabric patio habitat with light ceramic plates hung on its outer walls, 40 M.D.C. per side, roof and floor included; it becomes part of the robot, armour and all, with an internal hatch to the cockpit. Same fittings as the patio model, but two people need 60 minutes to assemble it.', 'Rifts World Book 34: Northern Gun Two p.255', NULL),
  ('ng-environmental-crew-compartment', 'Environmental Crew Compartment', 'rifts', 'gear', NULL, 50000, '50,000 credits for a single-pilot vehicle; 120,000-250,000 credits for a multi-person crew compartment.', NULL, 0, NULL, NULL, NULL, NULL, NULL, 25, 'Encloses an open cockpit on a vehicle or robot in light mega-damage plexiglass and plastic, 25 M.D.C. per panel, with at least one panel swivelling open as a door. Insulated, with a heater good to -30 F (-34 C) outside and a small air conditioner holding about 75 F (24 C). Not airtight.', 'Rifts World Book 34: Northern Gun Two p.255-256', NULL),
  ('ng-hammock-links', 'Hammock Links', 'rifts', 'gear', NULL, 300, '300 credits per pair of links, plus 300 credits per hammock.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Small tie-down hooks fitted at points on a robot''s or vehicle''s hull so mesh hammocks can be strung between them, a cheap alternative to a habitation module that sleeps crew off the ground. Most robots and large vehicles take four to six; the hammocks also lash down light cargo.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-vehicle-hot-plate', 'Vehicle Hot Plate', 'rifts', 'gear', NULL, 150, '150 credits portable plug-in; 2,500 credits fixed and wired into the vehicle''s power.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A field-proven cooker whose sprung, clamping cover holds the pot or pan in place, so a fight mid-meal does not scald the pilot. Plugs into a vehicle''s power port or is wired in at a fixed spot; some fold against the wall.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-vehicle-microwave', 'Vehicle Microwave', 'rifts', 'gear', NULL, 200, '200 credits portable plug-in; 3,000 credits fixed unit.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A compact oven for crews in the field whose front telescopes out to take bigger dishes, then slides back.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-vehicle-mini-fridge', 'Vehicle Mini-Fridge', 'rifts', 'gear', NULL, 300, '300 credits portable plug-in; 3,500 credits fixed unit.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A small vehicle refrigerator, about two shoeboxes in capacity, for food, drink or medical supplies such as plasma and vaccines.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-vehicle-water-cooler', 'Vehicle Water-Cooler', 'rifts', 'gear', NULL, 400, '400 credits portable plug-in; 3,200 credits fixed to a wall and wired into the vehicle''s power.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A 20 gallon (75.7 l) cooler giving fresh, cold drinking water on board.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-vehicle-electrical-outlet', 'Vehicle Electrical Outlet', 'rifts', 'gear', NULL, 1000, '1,000 credits each.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An extra power outlet fitted inside a vehicle for plug-in appliances. More than six is advised against, for clutter in a cramped space.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-sleeper-upgrade', 'Sleeper Upgrade', 'rifts', 'gear', NULL, 2400, '2,400 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Swaps the pilot''s seat for a padded recliner with a built-in blanket that pulls out and rewinds with a tug, an extending headrest, a curtain for the view ports and a wake-up alarm. Fits only full-size robots and vehicles whose crew compartment is enclosed; not hovercycles, motorcycles and the like.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-robot-tarp', 'Robot Tarp', 'rifts', 'gear', NULL, 600, '600 credits.', NULL, 0, NULL, NULL, NULL, NULL, 100, NULL, 'A huge camouflage sheet thrown over a giant robot or vehicle against rain, snow and dust, and to help hide it. Bulky even rolled up; covering a big machine may take another robot or two, or people with jet packs or power armor. 100 S.D.C.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-winterization-kit', 'Winterization Kit', 'rifts', 'gear', NULL, 1200, 'Hovercycles 1,200, power armor 2,000, wheeled vehicles 2,400, tracked vehicles 4,000, robots 5,000 credits.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Northern Gun''s cold-weather package: snow tires or tracks for ground vehicles, gripping rubber soles for robot feet, heated wire in hovercycle air filters, defrosters, and a heated ignition for non-nuclear engines that starts down to -30 F (-34.4 C). Halves every penalty for operating in snow and ice.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-bionic-thigh-holster-compartment', 'NG Bionic Thigh Holster Compartment', 'rifts', 'cybernetics', NULL, 2000, '2,000 credits exterior holster; 12,000 credits concealed version.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A holster built into a cyborg''s hip or thigh, either open or hidden as a secret compartment, so a sidearm is always to hand. Shaped for pistols and revolvers but holds E-Clips and other small items too; big guns such as the NG Super or Naruni pistols need a larger outside holster or a custom hidden compartment.', 'Rifts World Book 34: Northern Gun Two p.256', NULL),
  ('ng-bionic-vibro-harpoon-and-line', 'NG Bionic Vibro-Harpoon and Line', 'rifts', 'cybernetics', NULL, 20000, '20,000 credits.', '1D6 M.D. fired or used as a Vibro-Knife', 1, '100 ft (30.5 m) on its cable; 300 ft (91.4 m) with the line detached', NULL, NULL, NULL, NULL, NULL, 'A bionic launcher, like the grappling hook launcher, that fires a small Vibro-Harpoon on a thin 100 ft cable. Retractable barbs hold it fast, letting a cyborg spear large sea creatures or latch onto a passing boat to ride or climb aboard; the line holds 2,000 lbs (900 kg), enough for a 1,000+ pound Combat Cyborg.', 'Rifts World Book 34: Northern Gun Two p.256', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 28 gear rows are in' AS assertion, count(*) AS got, 28 AS want
  FROM gear WHERE slug IN ('ng-all-surface-climbing-gear', 'ng-s2-basic-survival-pack', 'ng-electronic-auto-lock-pick', 'ng-heads-up-display-glasses', 'ng-ipb-10-infrared-photo-binoculars', 'ng-overland-harness-and-frame-pack-mdc', 'ng-sleepsafe-personal-field-shelter', 'ng-sleepsafe-sensor-sentry', 'ng-sleepsafe-sentry-tent', 'ng-standard-tent-two-person', 'ng-icss-combat-and-survival-shelter-mdc', 'ng-ccs-command-and-control-shelter-mdc', 'ng-medical-bio-brace', 'ng-robot-habitation-module-fabric-carrier', 'ng-robot-habitation-module-fabric-patio', 'ng-robot-habitation-module-deluxe-armored', 'ng-environmental-crew-compartment', 'ng-hammock-links', 'ng-vehicle-hot-plate', 'ng-vehicle-microwave', 'ng-vehicle-mini-fridge', 'ng-vehicle-water-cooler', 'ng-vehicle-electrical-outlet', 'ng-sleeper-upgrade', 'ng-robot-tarp', 'ng-winterization-kit', 'ng-bionic-thigh-holster-compartment', 'ng-bionic-vibro-harpoon-and-line') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~334-northern-gun-2-adventuring-gear.sql');
